import{_ as r,o as a,c as t,a2 as i}from"./chunks/framework.CHeM0PsO.js";const l="/img/skill_need_tools.png",o="/img/github_projects.png",u=JSON.parse('{"title":"工具","description":"","frontmatter":{},"headers":[],"relativePath":"knowledge/tools.md","filePath":"knowledge/tools.md","lastUpdated":null}'),h={name:"knowledge/tools.md"};function p(n,e,c,s,w,m){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="工具" tabindex="-1">工具 <a class="header-anchor" href="#工具" aria-label="Permalink to &quot;工具&quot;">​</a></h1><p>工具只是工具，没有绝对的标准、只要适合就好</p><p><a href="https://tangjie.me/blog/184.html" target="_blank" rel="noreferrer">https://tangjie.me/blog/184.html</a></p><p><img src="'+l+'" alt="工作所需的工具"></p><p>TODO: 产品经理必用的软件大全—产品手记推荐工具系列 - 「已注销」的文章 - 知乎 <a href="https://zhuanlan.zhihu.com/p/109261065" target="_blank" rel="noreferrer">https://zhuanlan.zhihu.com/p/109261065</a></p><h2 id="project" tabindex="-1">Project <a class="header-anchor" href="#project" aria-label="Permalink to &quot;Project&quot;">​</a></h2><p>Microsoft Project</p><p>适用平台：Windows&amp;Mac</p><p>软件特点：</p><ul><li>全能型项目管理工具；</li><li>Microsoft家族软件成员；</li><li>无需联网即可使用；</li><li>有资源管理和人员管理模块；</li><li>有甘特图、燃尽图等模板；</li></ul><p>缺点：</p><ul><li>收费，有永久激活版；</li><li>无法多人协作；</li><li>共享和演示功能弱；</li></ul><p>甘特图：<a href="https://support.microsoft.com/zh-cn/office/%E4%BD%BF%E7%94%A8%E7%94%98%E7%89%B9%E5%9B%BE%E8%A7%86%E5%9B%BE-0e84efa4-78ce-4cd1-baed-5159a55f78b4" target="_blank" rel="noreferrer">https://support.microsoft.com/zh-cn/office/使用甘特图视图-0e84efa4-78ce-4cd1-baed-5159a55f78b4</a></p><ul><li><a href="https://www.iamxiarui.com/?paged=3&amp;cat=111" target="_blank" rel="noreferrer">https://www.iamxiarui.com/?paged=3&amp;cat=111</a></li><li><a href="https://blog.csdn.net/liwei16611/article/details/100106262##" target="_blank" rel="noreferrer">https://blog.csdn.net/liwei16611/article/details/100106262##</a> UML</li></ul><p><a href="https://www.iamxiarui.com/?p=1231" target="_blank" rel="noreferrer">https://www.iamxiarui.com/?p=1231</a></p><p><img src="'+o+'" alt="Github project"></p><h2 id="axure-1" tabindex="-1">Axure <a href="https://www.yinxiang.com/everhub/note/435c8b2c-9127-43f3-a6e3-fc5f8898d893" target="_blank" rel="noreferrer">1</a> <a class="header-anchor" href="#axure-1" aria-label="Permalink to &quot;Axure [1]&quot;">​</a></h2><p>Axure 9.0不用？<a href="https://www.bilibili.com/video/BV1it41137Xg?p=2" target="_blank" rel="noreferrer">4</a> 口碑差，实际上都用8.0、8.1</p><p><strong>Axure实战</strong>见 <a href="https://github.com/StevenJokess/2bPM/blob/master/src/meituan_PM_recovered.rp" target="_blank" rel="noreferrer">https://github.com/StevenJokess/2bPM/blob/master/src/meituan_PM_recovered.rp</a></p><ul><li>流程图实战 :ref:<code>flow_chart_Axure</code></li><li>流程图页面化实战 :ref:<code>flow_chart2page_Axure</code></li><li>低保真页面实战 :ref:<code>page_Axure</code></li><li>高保真页面实战 :ref:<code>page_done_Axure</code></li></ul><p>更多：</p><ul><li><a href="https://www.axure.com.cn/axure/" target="_blank" rel="noreferrer">https://www.axure.com.cn/axure/</a></li><li>AxureShop：<a href="https://www.axureshop.com/" target="_blank" rel="noreferrer">https://www.axureshop.com/</a></li><li><a href="https://axhub.im/" target="_blank" rel="noreferrer">https://axhub.im/</a></li><li>AXURE8 原型绘制效率工具：<a href="https://coffee.pmcaff.com/article/2111722865562752/pmcaff?utm_source=forum&amp;newwindow=1" target="_blank" rel="noreferrer">https://coffee.pmcaff.com/article/2111722865562752/pmcaff?utm_source=forum&amp;newwindow=1</a></li><li>AXURE8 教学（从8到9，布局快捷键大变，更不方便，一步交互变四步，多目标藏+好里，很多bug）：<a href="https://www.bilibili.com/video/BV1bt41137MY" target="_blank" rel="noreferrer">https://www.bilibili.com/video/BV1bt41137MY</a></li><li>AXURE8：<a href="http://www.woshipm.com/xiazai/188927.html" target="_blank" rel="noreferrer">http://www.woshipm.com/xiazai/188927.html</a></li><li>Axure（8+9）产品经理：<a href="https://edu.csdn.net/course/play/28296/389326" target="_blank" rel="noreferrer">https://edu.csdn.net/course/play/28296/389326</a></li><li>Axhub 即Axure原型发布与协作平台：<a href="https://axhub.im/" target="_blank" rel="noreferrer">https://axhub.im/</a></li><li><a href="https://chanpinyx.com/" target="_blank" rel="noreferrer">https://chanpinyx.com/</a></li><li><a href="http://www.iaxure.com/" target="_blank" rel="noreferrer">http://www.iaxure.com/</a></li></ul><h3 id="简介" tabindex="-1">简介 <a class="header-anchor" href="#简介" aria-label="Permalink to &quot;简介&quot;">​</a></h3><p><a href="https://www.iamxiarui.com/?p=1845" target="_blank" rel="noreferrer">https://www.iamxiarui.com/?p=1845</a></p><p>在我的实践中，用Axure原型+注释的方式撰写，导出HTML或发布到Axshare或通过蓝湖上传的方式传达；效率最高效果最好。</p><p>Axure之于产品经理就像PhotoShop之于设计师</p><p>经典的虽然看起来没那么酷炫，但是它代表着易用性、拓展性、普适性</p><ul><li><p>易用性：可以找到大量教程，降低门槛快速上手</p></li><li><p>拓展性：可以获取大量素材，积累提升输出质量</p></li><li><p>普适性：可以兼容各种系统，提升工作协同效率</p></li><li><p>有人用墨刀做花里胡哨的交互，文字描述寥寥，结果连异常流程都覆盖不了</p></li><li><p>有人用word写长篇大论，结果开发根本不看，还要问你每个页面怎么跳转</p></li><li><p>有人用sketch，不配合专属插件的话，很容易画成没有结构性的页面流程图。而且是否具备普适性，取决于周围与你配合的人</p></li></ul><p>工具本身没有问题，有问题一定是工具人的问题。</p><p>为了让你的PRD的用户使用效果更好，汲取意见是很重要的。有的时候不要埋怨开发为什么不认真看，去问问他们喜欢看什么样的，适当调整达成统一。</p><p>Tower、禅道、tapd等团队协同工具，会导致一部分人习惯把产品的结构通过协同工具中的单个需求建立父子关系连接，在每个子需求中上传需求图片+文字描述。这种方式更适合优化已有功能，功能可以在小范围内实现闭环，但是容易使人忽略细节的调整对全局的影响。</p><p>产品经理应该把控Axure源文件的颗粒度，哪些版本/模块在一个源文件里更新，从哪个版本/模块新建文档维护；文档或文件夹之间尽量去重、解耦。在原有文件上新增或调整的部分，更显眼的做出标注，让人可以一眼看出变动的部分。</p><p>在Axure里搭建当前版本/模块最完整的产品结构，并且及时更新。要明确一个认知，协同工具是给UI、开发、测试、运营看的，目的是让他们看起来方便，可以针对单个需求设置执行人员、排期、添加bug记录等，核心价值是项目管理。而不是为了产品经理维护需求文档方便，所以在需求的撰写和管理时，不要依赖协同工具。在追溯需求问题的时候，要能做到在Axure文件里便能找到记录，而不是去翻协同工具里的需求记录。</p><p>Axure基础操作总结：<a href="https://blog.csdn.net/zcl050505/article/details/110439551" target="_blank" rel="noreferrer">https://blog.csdn.net/zcl050505/article/details/110439551</a></p><h2 id="visio" tabindex="-1">Visio <a class="header-anchor" href="#visio" aria-label="Permalink to &quot;Visio&quot;">​</a></h2><p>画泳道图<a href="https://www.zhihu.com/column/c_199236458" target="_blank" rel="noreferrer">6</a></p><h2 id="sketch-5" tabindex="-1">Sketch <a href="https://blog.csdn.net/Dylan_zhijing/article/details/107825514?spm=1001.2014.3001.5502" target="_blank" rel="noreferrer">5</a> <a class="header-anchor" href="#sketch-5" aria-label="Permalink to &quot;Sketch [5]&quot;">​</a></h2><p>Sketch有利于产品与UI的协同工作。对于较小的需求，在白板上画出原型后可以直接进入UI阶段。</p><p>优点：</p><ul><li>方便画出高保真的原型图；</li><li>在静态界面的展示方面有一定优势；</li><li>无限画布，可以将各页面放到一个画布上帮助串联思考。</li></ul><p>不足：</p><ul><li>对于初学者，基础功能的学习成本较高；</li><li>Sketch作为一款设计工具，会让使用者陷入“设计者思维”，在细节上耗费较多时间，拖延项目进度。</li></ul><h2 id="tapd" tabindex="-1">TAPD <a class="header-anchor" href="#tapd" aria-label="Permalink to &quot;TAPD&quot;">​</a></h2><p>TAPD开放产品，包含两个解决方案-轻量协作和敏捷研发。轻量协作：对标Tower，功能特点为看板+云文档+企业微信集成，为满足小团队的协作需要。敏捷研发功能特点包含需求、迭代、缺陷、测试计划／用例、发布评审、看板等。总体来看敏捷研发特性（能力）更强。整体UI特点：偏传统，多页应用。</p><p><a href="https://www.zhihu.com/question/56575428/answer/352398510" target="_blank" rel="noreferrer">https://www.zhihu.com/question/56575428/answer/352398510</a></p><h2 id="markdown" tabindex="-1">Markdown <a class="header-anchor" href="#markdown" aria-label="Permalink to &quot;Markdown&quot;">​</a></h2><ul><li>Markdown保姆级教程之画图篇（流程图、序列图、饼图、甘特图）: <a href="https://www.bilibili.com/video/av88551739/" target="_blank" rel="noreferrer">https://www.bilibili.com/video/av88551739/</a></li><li>官方帮助文档：<a href="https://mermaid-js.github.io/mermaid/#/flowchart" target="_blank" rel="noreferrer">https://mermaid-js.github.io/mermaid/#/flowchart</a></li><li>VScode插件：Markdown Preview Mermaid Support</li><li>更多：<a href="https://www.iminho.me/wiki/docs/mindoc/mermaid.md" target="_blank" rel="noreferrer">https://www.iminho.me/wiki/docs/mindoc/mermaid.md</a></li></ul><h2 id="眼界" tabindex="-1">眼界 <a class="header-anchor" href="#眼界" aria-label="Permalink to &quot;眼界&quot;">​</a></h2><ul><li>快懂百科：<a href="https://www.baike.com/" target="_blank" rel="noreferrer">https://www.baike.com/</a></li><li>中文互联网数据资讯网：<a href="http://www.199it.com/" target="_blank" rel="noreferrer">http://www.199it.com/</a></li><li>FT中文网：<a href="https://www.ftchinese.com/" target="_blank" rel="noreferrer">https://www.ftchinese.com/</a></li><li>品玩：<a href="https://www.pingwest.com/" target="_blank" rel="noreferrer">https://www.pingwest.com/</a></li><li>最新高质量的专业资讯、数据：<a href="https://www.zhihu.com/question/367641344" target="_blank" rel="noreferrer">https://www.zhihu.com/question/367641344</a></li></ul>',49)])])}const d=r(h,[["render",p]]);export{u as __pageData,d as default};
